<template><ForgeDialog title="Chmod calculator" description="Build Unix permissions and copy the matching chmod command." eyebrow="WORKSPACE / FILES" @close="emit('close')"><div class="chmod-panel"><div class="chmod-table"><div></div><b>Owner</b><b>Group</b><b>Public</b><template v-for="permission in permissions" :key="permission.key"><span>{{ permission.label }}</span><label v-for="scope in scopes" :key="scope" class="chmod-check"><input v-model="values[scope][permission.key]" type="checkbox" /><small>{{ scope }}</small></label></template></div><div class="chmod-result"><span>Octal</span><b>{{ octal }}</b><span>Symbolic</span><b>{{ symbolic }}</b><code>chmod {{ octal }} path</code></div><button class="primary-button" @click="copy">Copy command</button></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, reactive } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { clipboard } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const scopes=['owner','group','public'] as const; const permissions=[{key:'read',label:'Read (4)'},{key:'write',label:'Write (2)'},{key:'execute',label:'Execute (1)'}] as const; const values=reactive<any>({owner:{read:false,write:false,execute:false},group:{read:false,write:false,execute:false},public:{read:false,write:false,execute:false}}); const octal=computed(()=>scopes.map(scope=>(values[scope].read?4:0)+(values[scope].write?2:0)+(values[scope].execute?1:0)).join('')); const symbolic=computed(()=>scopes.map(scope=>(values[scope].read?'r':'-')+(values[scope].write?'w':'-')+(values[scope].execute?'x':'-')).join('')); const copy=()=>clipboard.writeText('chmod '+octal.value+' path')
</script>
<style scoped>.chmod-panel{display:grid;gap:18px}.chmod-table{display:grid;grid-template-columns:1.3fr repeat(3,1fr);gap:6px;align-items:center}.chmod-table>*{padding:8px;border-bottom:1px solid var(--pqt-border)}.chmod-table b{text-align:center;color:var(--pqt-text)}.chmod-check{display:flex;justify-content:center;gap:5px;color:var(--pqt-text-muted)}.chmod-check small{font-size:9px}.chmod-result{display:grid;grid-template-columns:100px 1fr;gap:8px;padding:14px;border:1px solid var(--pqt-border);border-radius:8px}.chmod-result span{color:var(--pqt-text-muted);text-transform:uppercase;font-size:10px}.chmod-result b{color:var(--pqt-accent);font:18px var(--pqt-font-mono)}.chmod-result code{grid-column:1/-1;padding-top:8px;color:var(--pqt-text);font:12px var(--pqt-font-mono)}</style>
